function rampartSimulate(createStrategy, seed, maxTicks, observer) {
  var TN = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var TD = {
    bolt: { c: 50, d: 26, p: 8, r: 300, s: 0, sl: 0, pi: 0, g: 1, a: 1 },
    cannon: { c: 90, d: 60, p: 24, r: 260, s: 90, sl: 0, pi: 0, g: 1, a: 0 },
    frost: { c: 70, d: 10, p: 12, r: 240, s: 0, sl: 30, pi: 0, g: 1, a: 1 },
    lance: { c: 120, d: 180, p: 36, r: 360, s: 0, sl: 0, pi: 1, g: 1, a: 0 },
    flak: { c: 80, d: 40, p: 10, r: 320, s: 70, sl: 0, pi: 0, g: 0, a: 1 }
  };
  var ED = {
    grunt: { hp: 60, sp: 10, bo: 4, lk: 1, air: 0, fw: 1, wt: 10 },
    runner: { hp: 40, sp: 20, bo: 4, lk: 1, air: 0, fw: 2, wt: 4 },
    wisp: { hp: 50, sp: 12, bo: 6, lk: 2, air: 1, fw: 3, wt: 3 },
    brute: { hp: 150, sp: 6, bo: 9, lk: 3, air: 0, fw: 4, wt: 3 },
    splitter: { hp: 90, sp: 8, bo: 6, lk: 2, air: 0, fw: 6, wt: 2 },
    mender: { hp: 70, sp: 8, bo: 7, lk: 2, air: 0, fw: 8, wt: 1 },
    splitling: { hp: 0, sp: 12, bo: 1, lk: 1, air: 0, fw: 9999, wt: 0 }
  };
  var ORDER = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  function mkRoute(pts) {
    var segs = [], L = 0;
    for (var i = 0; i + 1 < pts.length; i++) {
      var ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50, bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
      var len = Math.abs(bx - ax) + Math.abs(by - ay);
      segs.push({ ax: ax, ay: ay, dx: Math.sign(bx - ax), dy: Math.sign(by - ay), s: L, len: len });
      L += len;
    }
    return { segs: segs, L: L };
  }
  var GR = mkRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]);
  var AR = mkRoute([[0, 6], [21, 6], [21, 11], [23, 11]]);
  function place(e) {
    var r = e.air ? AR : GR, sg = r.segs;
    for (var i = 0; i < sg.length; i++) {
      var q = sg[i];
      if (e.progress <= q.s + q.len || i === sg.length - 1) {
        var d = e.progress - q.s; e.x = q.ax + q.dx * d; e.y = q.ay + q.dy * d; return;
      }
    }
  }
  var SL = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var M = [0, 1000];
  function mult(w) { while (M.length <= w) M.push(Math.floor(M[M.length - 1] * 108 / 100)); return M[w]; }
  function armorOf(t, w) { return t === 'grunt' ? Math.floor(w / 4) : t === 'brute' ? 6 + w : 0; }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), types = [], tot = 0, out = [];
    for (var i = 0; i < ORDER.length; i++) if (ED[ORDER[i]].fw <= w) { types.push(ORDER[i]); tot += ED[ORDER[i]].wt; }
    for (var j = 0; j < n; j++) {
      var r = rng() % tot;
      for (var k = 0; k < types.length; k++) { var wt = ED[types[k]].wt; if (r < wt) { out.push(types[k]); break; } r -= wt; }
    }
    return out;
  }
  function stats(t) {
    var b = TD[t.type], d = b.d;
    for (var i = 1; i < t.tier; i++) d = Math.floor(d * 16 / 10);
    return { d: d, r: b.r + 30 * (t.tier - 1) };
  }
  function view(e) {
    var rt = e.air ? AR : GR;
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: rt.L - e.progress };
  }
  var gold = 250, baseHp = 10, wave = 0, nextComp = genWave(1), turrets = [], enemies = [], queue = [], nextId = 1, log = [];
  for (var i = 0; i < 16; i++) turrets.push(null);
  var strat = createStrategy();
  var fallTick = -1, endTick = maxTicks;
  var ev = null;
  function mkEnemy(type, w, maxHp, progress) {
    var d = ED[type];
    var e = { id: nextId++, type: type, wave: w, maxHp: maxHp, hp: maxHp, armor: armorOf(type, w), speed: d.sp, air: d.air,
      progress: progress, age: 0, slow: 0, x: 0, y: 0 };
    place(e); return e;
  }
  for (var tick = 0; tick < maxTicks; tick++) {
    if (observer) ev = { shots: [], kills: [], heals: [], leaks: [], actions: [], spawns: [] };
    // 1 wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1; wave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      var comp = nextComp; nextComp = genWave(w + 1);
      var st = { tick: tick, wave: w, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: nextComp.slice() };
      for (var s = 0; s < 16; s++) st.slots.push({ slot: s, x: SL[s][0] * 100 + 50, y: SL[s][1] * 100 + 50,
        turret: turrets[s] ? { type: turrets[s].type, tier: turrets[s].tier, spent: turrets[s].spent } : null });
      for (var q = 0; q < enemies.length; q++) st.enemies.push(view(enemies[q]));
      var acts = strat.plan(st);
      if (acts && acts.length) {
        for (var ai = 0; ai < acts.length && ai < 32; ai++) {
          var A = acts[ai]; if (!A || typeof A !== 'object') continue;
          var sl = A.slot;
          if (typeof sl !== 'number' || sl < 0 || sl > 15 || (sl | 0) !== sl) continue;
          if (A.op === 'build') {
            if (turrets[sl] || !TD.hasOwnProperty(A.type)) continue;
            var c = TD[A.type].c; if (gold < c) continue;
            gold -= c; turrets[sl] = { slot: sl, type: A.type, tier: 1, spent: c, cd: 0, x: SL[sl][0] * 100 + 50, y: SL[sl][1] * 100 + 50 };
            log.push([tick, 'B', sl, TN.indexOf(A.type)]); if (ev) ev.actions.push(['B', sl]);
          } else if (A.op === 'upgrade') {
            var T = turrets[sl]; if (!T || T.tier >= 3) continue;
            var uc = TD[T.type].c * T.tier; if (gold < uc) continue;
            gold -= uc; T.spent += uc; T.tier++;
            log.push([tick, 'U', sl, T.tier]); if (ev) ev.actions.push(['U', sl]);
          } else if (A.op === 'sell') {
            var T2 = turrets[sl]; if (!T2) continue;
            gold += Math.floor(T2.spent * 70 / 100); turrets[sl] = null;
            log.push([tick, 'S', sl, 0]); if (ev) ev.actions.push(['S', sl, T2.type]);
          }
        }
      }
      for (var k = 0; k < comp.length; k++) queue.push({ t: tick + 4 * k, w: w, i: k, type: comp[k] });
      queue.sort(function (a, b) { return a.t - b.t || a.w - b.w || a.i - b.i; });
    }
    // 2 spawn
    while (queue.length && queue[0].t === tick) {
      var qq = queue.shift();
      var e0 = mkEnemy(qq.type, qq.w, Math.floor(ED[qq.type].hp * mult(qq.w) / 1000), 0);
      enemies.push(e0); if (ev) ev.spawns.push(e0.id);
    }
    // 3 move
    var fell = false, keep = [];
    for (var m = 0; m < enemies.length; m++) {
      var e = enemies[m];
      if (fell) { keep.push(e); continue; }
      var L = e.air ? AR.L : GR.L;
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= L) {
        e.progress = L; place(e);
        baseHp -= ED[e.type].lk;
        log.push([tick, 'L', e.id, baseHp]); if (ev) ev.leaks.push({ id: e.id, hp: baseHp });
        if (baseHp <= 0) { fell = true; log.push([tick, 'F', wave, 0]); }
      } else { place(e); keep.push(e); }
    }
    enemies = keep;
    if (fell) { fallTick = tick; endTick = tick; if (observer) observer(tick, { enemies: enemies, turrets: turrets, gold: gold, baseHp: baseHp, wave: wave, ev: ev, fell: true, nextWave: nextComp }); break; }
    // 4 age & heal
    for (var h = 0; h < enemies.length; h++) {
      var me = enemies[h]; me.age++;
      if (me.type === 'mender' && me.age % 20 === 0) {
        for (var h2 = 0; h2 < enemies.length; h2++) {
          var o = enemies[h2], ddx = o.x - me.x, ddy = o.y - me.y;
          if (ddx * ddx + ddy * ddy <= 22500) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
        }
        if (ev) ev.heals.push({ x: me.x, y: me.y });
      }
    }
    // 5 fire
    for (var ts = 0; ts < 16; ts++) {
      var tu = turrets[ts]; if (!tu) continue;
      if (tu.cd > 0) { tu.cd--; if (tu.cd > 0) continue; }
      var b = TD[tu.type], sv = stats(tu), r2 = sv.r * sv.r, cands = [];
      for (var ci = 0; ci < enemies.length; ci++) {
        var ce = enemies[ci];
        if (ce.hp <= 0) continue;
        if (ce.air ? !b.a : !b.g) continue;
        var ex = ce.x - tu.x, ey = ce.y - tu.y;
        if (ex * ex + ey * ey <= r2) cands.push(ce);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (typeof strat.target === 'function') {
        var cv = []; for (var vi = 0; vi < cands.length; vi++) cv.push(view(cands[vi]));
        var id = strat.target({ slot: ts, type: tu.type, tier: tu.tier, x: tu.x, y: tu.y, range: sv.r }, cv);
        for (var vj = 0; vj < cands.length; vj++) if (cands[vj].id === id) { tgt = cands[vj]; break; }
      }
      if (!tgt) {
        var best = null, br = 0;
        for (var dj = 0; dj < cands.length; dj++) {
          var rr = (cands[dj].air ? AR.L : GR.L) - cands[dj].progress;
          if (best === null || rr < br) { best = cands[dj]; br = rr; }
        }
        tgt = best;
      }
      var hits = [];
      if (b.s > 0) {
        var s2 = b.s * b.s;
        for (var hi = 0; hi < enemies.length; hi++) {
          var he = enemies[hi]; if (he.hp <= 0) continue;
          if (he.air ? !b.a : !b.g) continue;
          var hx = he.x - tgt.x, hy = he.y - tgt.y;
          if (hx * hx + hy * hy <= s2) hits.push(he);
        }
      } else hits.push(tgt);
      for (var hk = 0; hk < hits.length; hk++) {
        var hz = hits[hk];
        var dmg = b.pi ? sv.d : Math.max(1, sv.d - hz.armor);
        hz.hp -= dmg; if (b.sl) hz.slow = b.sl;
      }
      tu.cd = b.p;
      if (ev) ev.shots.push({ slot: ts, type: tu.type, x: tgt.x, y: tgt.y, air: tgt.air, id: tgt.id });
      var alive = [], born = [];
      for (var di = 0; di < enemies.length; di++) {
        var de = enemies[di];
        if (de.hp <= 0) {
          gold += ED[de.type].bo; log.push([tick, 'K', de.id, ts]);
          if (ev) ev.kills.push({ id: de.id, type: de.type, x: de.x, y: de.y, air: de.air });
          if (de.type === 'splitter') {
            var shp = Math.max(1, Math.floor(de.maxHp / 4));
            for (var sp = 0; sp < 3; sp++) { var ne = mkEnemy('splitling', de.wave, shp, de.progress); born.push(ne); if (ev) ev.spawns.push(ne.id); }
          }
        } else alive.push(de);
      }
      enemies = alive.concat(born);
    }
    // 6 slow
    for (var si = 0; si < enemies.length; si++) if (enemies[si].slow > 0) enemies[si].slow--;
    if (observer) observer(tick, { enemies: enemies, turrets: turrets, gold: gold, baseHp: baseHp, wave: wave, ev: ev, fell: false, nextWave: nextComp });
  }
  var js = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var u = 0; u < js.length; u++) { hsh ^= js.charCodeAt(u); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16); while (hex.length < 8) hex = '0' + hex;
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: hex };
}
