  };
  if (P) for (var pk in P) K[pk] = P[pk];
  var TD = {
    bolt: { c: 50, d: 26, p: 8, r: 300, g: 1, a: 1, pi: 0 },
    cannon: { c: 90, d: 60, p: 24, r: 260, g: 1, a: 0, pi: 0 },
    frost: { c: 70, d: 10, p: 12, r: 240, g: 1, a: 1, pi: 0 },
    lance: { c: 120, d: 180, p: 36, r: 360, g: 1, a: 0, pi: 1 },
    flak: { c: 80, d: 40, p: 10, r: 320, g: 0, a: 1, pi: 0 }
  };
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var EH = { grunt: 60, runner: 40, wisp: 50, brute: 150, splitter: 90, mender: 70 };
  var LK = { grunt: 1, runner: 1, wisp: 2, brute: 3, splitter: 2, mender: 2 };
  function poly(pts) {
    var out = [];
    for (var i = 0; i + 1 < pts.length; i++) {
      var ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50, bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
      var n = (Math.abs(bx - ax) + Math.abs(by - ay)) / 10;
      for (var k = 0; k < n; k++) out.push([ax + (bx - ax) * k / n, ay + (by - ay) * k / n]);
    }
    return out;
  }
  var GP = poly([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]);
  var AP = poly([[0, 6], [21, 6], [21, 11], [23, 11]]);
  function cover(path, x, y, r) {
    var c = 0;
    for (var i = 0; i < path.length; i++) { var dx = path[i][0] - x, dy = path[i][1] - y; if (dx * dx + dy * dy <= r * r) c++; }
    return c * 10;
  }
